_choice_preview_window() {
    {
        printf '%s\n' up down left right next
        printf '%s\n' wrap no-wrap wrap-word no-wrap-word
        printf '%s\n' cycle no-cycle follow no-follow info no-info hidden no-hidden default
        local style
        for style in $(_helper_fzf_border_styles); do
